ALTER TABLE customers ADD COLUMN duplicate_review_reason varchar(500),ADD COLUMN address varchar(1000),ADD COLUMN city varchar(100),ADD COLUMN country varchar(80) NOT NULL DEFAULT 'India',ADD COLUMN status varchar(16) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(),ADD COLUMN version bigint NOT NULL DEFAULT 0;
ALTER TABLE customers ADD COLUMN normalized_email text GENERATED ALWAYS AS (nullif(lower(trim(email)),'')) STORED, ADD COLUMN normalized_phone text GENERATED ALWAYS AS (CASE WHEN country IN ('India','IN') AND length(regexp_replace(coalesce(phone,''),'[^0-9]','','g'))=10 THEN '91'||regexp_replace(phone,'[^0-9]','','g') ELSE nullif(regexp_replace(regexp_replace(phone,'[^0-9]','','g'),'^00',''),'') END) STORED;
CREATE INDEX customer_contact_email ON customers(tenant_id,normalized_email);
CREATE INDEX customer_contact_phone ON customers(tenant_id,normalized_phone);
CREATE INDEX customer_directory ON customers(tenant_id,status,created_at DESC,id);
CREATE TABLE customer_contacts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,customer_id uuid NOT NULL,kind varchar(12) NOT NULL CHECK(kind IN ('EMAIL','PHONE')),label varchar(60) NOT NULL,value varchar(254) NOT NULL,normalized_value text NOT NULL,status varchar(16) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id));
CREATE UNIQUE INDEX contact_identity ON customer_contacts(tenant_id,customer_id,kind,normalized_value) WHERE status='ACTIVE';
CREATE INDEX contact_lookup ON customer_contacts(tenant_id,kind,normalized_value) WHERE status='ACTIVE';
ALTER TABLE vehicles ADD COLUMN vin varchar(17),ADD COLUMN year integer CHECK(year BETWEEN 1900 AND 2200),ADD COLUMN fuel_type varchar(24),ADD COLUMN color varchar(60),ADD COLUMN status varchar(16) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),ADD COLUMN registration_branch_id uuid,ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(),ADD COLUMN version bigint NOT NULL DEFAULT 0,ADD COLUMN identifier_conflict boolean NOT NULL DEFAULT false;
ALTER TABLE vehicles ADD COLUMN normalized_registration text GENERATED ALWAYS AS (regexp_replace(upper(registration),'[^A-Z0-9]','','g')) STORED;
UPDATE vehicles SET identifier_conflict=true WHERE (tenant_id,normalized_registration) IN (SELECT tenant_id,normalized_registration FROM vehicles GROUP BY tenant_id,normalized_registration HAVING count(*)>1);
CREATE UNIQUE INDEX vehicle_registration_identity ON vehicles(tenant_id,normalized_registration) WHERE NOT identifier_conflict;
CREATE UNIQUE INDEX vehicle_vin_identity ON vehicles(tenant_id,vin) WHERE vin IS NOT NULL;
CREATE INDEX vehicle_directory ON vehicles(tenant_id,status,created_at DESC,id);
CREATE TABLE vehicle_ownerships(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,vehicle_id uuid NOT NULL,customer_id uuid NOT NULL,started_at timestamptz NOT NULL,ended_at timestamptz,reason varchar(500) NOT NULL,actor_id uuid,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,vehicle_id) REFERENCES vehicles(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id),CHECK(ended_at IS NULL OR ended_at>=started_at));
CREATE UNIQUE INDEX one_current_owner ON vehicle_ownerships(tenant_id,vehicle_id) WHERE ended_at IS NULL;
CREATE INDEX ownership_customer ON vehicle_ownerships(tenant_id,customer_id,started_at DESC);
INSERT INTO vehicle_ownerships(id,tenant_id,vehicle_id,customer_id,started_at,reason) SELECT id,tenant_id,id,customer_id,created_at,'Preserved Milestone 1 ownership' FROM vehicles;
CREATE TABLE odometer_records(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,vehicle_id uuid NOT NULL,branch_id uuid NOT NULL,kilometers bigint NOT NULL CHECK(kilometers BETWEEN 0 AND 9999999),recorded_at timestamptz NOT NULL,actor_id uuid NOT NULL,note varchar(500),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,vehicle_id) REFERENCES vehicles(tenant_id,id));
CREATE INDEX odometer_vehicle ON odometer_records(tenant_id,vehicle_id,recorded_at DESC,id);
CREATE TABLE documents(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,vehicle_id uuid,customer_id uuid,branch_id uuid NOT NULL,object_key text NOT NULL UNIQUE,file_name varchar(180) NOT NULL,content_type varchar(80) NOT NULL,byte_size bigint NOT NULL CHECK(byte_size BETWEEN 1 AND 10485760),sha256 varchar(64) NOT NULL,visibility varchar(24) NOT NULL CHECK(visibility IN ('TECHNICAL','CUSTOMER_PRIVATE')),status varchar(16) NOT NULL CHECK(status IN ('PENDING','AVAILABLE','REJECTED','DELETED')),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 0,FOREIGN KEY(tenant_id,vehicle_id) REFERENCES vehicles(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id),CHECK((vehicle_id IS NULL)!=(customer_id IS NULL)));
CREATE INDEX documents_vehicle ON documents(tenant_id,vehicle_id,status,created_at DESC,id);
CREATE INDEX documents_customer ON documents(tenant_id,customer_id,status,created_at DESC,id);
CREATE TABLE registry_audit(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,actor_id uuid NOT NULL,branch_id uuid,action varchar(80) NOT NULL,target_id uuid NOT NULL,outcome varchar(24) NOT NULL,correlation_id varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX registry_audit_tenant ON registry_audit(tenant_id,created_at DESC,id);
